using System;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Web.Script.Serialization;
public class CodexQuotaReset {
 public int Minutes;public string Kind;public DateTime ObservedUtc,PreviousCheckedUtc,PreviousResetUtc,NewResetUtc;public double PreviousRemaining,Remaining;
 public string Report(){return (Minutes==300?"五小时":"周")+"额度 · "+(Kind=="scheduled"?"新周期已检测到":"额度提前回升（疑似重置或调整）")+"\n首次检测 "+ObservedUtc.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss")+" · 前次核验 "+PreviousCheckedUtc.ToLocalTime().ToString("MM-dd HH:mm:ss")+"\n剩余 "+PreviousRemaining.ToString("F1")+"% → "+Remaining.ToString("F1")+"% · 上次预计重置 "+PreviousResetUtc.ToLocalTime().ToString("MM-dd HH:mm:ss")+" · 新预计重置 "+NewResetUtc.ToLocalTime().ToString("MM-dd HH:mm:ss");}
}
public class QuotaResetReminder {public int Minutes,LeadMinutes;public DateTime ResetUtc;public string Text;}
public sealed partial class CodexQuotaReader {
 public bool Dirty;
 internal static string AccountFingerprint(object result){var root=result as Dictionary<string,object>;object value;if(root==null||!root.TryGetValue("account",out value))return "";var account=value as Dictionary<string,object>;if(account==null)return "";object identity;if(!account.TryGetValue("id",out identity)&&!account.TryGetValue("email",out identity))return "";string text=Convert.ToString(identity).Trim().ToLowerInvariant();if(text.Length==0)return "";using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(text))).Replace("-","");}
 public static string Countdown(CodexQuotaSnapshot snapshot,int minutes,DateTime now){var w=snapshot==null?null:snapshot.Windows.FirstOrDefault(x=>x.Minutes==minutes);if(w==null)return "未返回重置时间";var left=w.ResetUtc-now;if(left<=TimeSpan.Zero)return "等待官方确认新周期";string time=(left.Days>0?left.Days+"天 ":"")+left.Hours.ToString("D2")+":"+left.Minutes.ToString("D2")+":"+left.Seconds.ToString("D2");return (now-snapshot.CheckedUtc>TimeSpan.FromMinutes(5)?"上次预计 · ":"")+time;}
 public CodexQuotaReset[] ObserveResets(CodexQuotaSnapshot s,CodexQuotaConfig cfg,DateTime now){var events=new List<CodexQuotaReset>();if(!cfg.Enabled||s==null||s.Windows.Count==0||s.CheckedUtc>now||now-s.CheckedUtc>TimeSpan.FromMinutes(5))return events.ToArray();var old=cfg.LastObserved;if(old!=null&&s.CheckedUtc<=old.CheckedUtc)return events.ToArray();if(old!=null&&s.AccountKey!=old.AccountKey)alerted.Clear();if(cfg.ResetHistory==null)cfg.ResetHistory=new List<CodexQuotaReset>();if(cfg.SentResetReminders==null)cfg.SentResetReminders=new List<string>();
  // Never infer an unscheduled reset across a login change or an unknown identity.
  if(old!=null&&!String.IsNullOrEmpty(s.AccountKey)&&s.AccountKey==old.AccountKey){foreach(var w in s.Windows){var previous=old.Windows.FirstOrDefault(x=>x.Minutes==w.Minutes);if(previous==null)continue;bool scheduled=previous.ResetUtc<=s.CheckedUtc&&w.ResetUtc>previous.ResetUtc;bool early=previous.ResetUtc>s.CheckedUtc&&(w.ResetUtc>previous.ResetUtc.AddMinutes(1)||w.Remaining-previous.Remaining>=10||w.Remaining>=99.5&&previous.Remaining<99.5);if(!scheduled&&!early)continue;var item=new CodexQuotaReset{Minutes=w.Minutes,Kind=scheduled?"scheduled":"early",ObservedUtc=s.CheckedUtc,PreviousCheckedUtc=old.CheckedUtc,PreviousResetUtc=previous.ResetUtc,NewResetUtc=w.ResetUtc,PreviousRemaining=previous.Remaining,Remaining=w.Remaining};events.Add(item);cfg.ResetHistory.Add(item);}}
  cfg.ResetHistory=cfg.ResetHistory.Skip(Math.Max(0,cfg.ResetHistory.Count-100)).ToList();cfg.LastObserved=new JavaScriptSerializer().Deserialize<CodexQuotaSnapshot>(new JavaScriptSerializer().Serialize(s));Dirty=true;return events.ToArray();
 }
 public QuotaResetReminder[] ResetReminderNotices(CodexQuotaSnapshot s,CodexQuotaConfig cfg,DateTime now){var messages=new List<QuotaResetReminder>();if(!cfg.Enabled||!cfg.ResetReminder||s==null)return messages.ToArray();if(cfg.SentResetReminders==null)cfg.SentResetReminders=new List<string>();var points=(cfg.ResetReminderPoints??new List<int>{Math.Max(1,Math.Min(60,cfg.ResetReminderMinutes))}).Where(p=>p>=1&&p<=1440).Distinct().OrderBy(p=>p).Take(12).ToArray();foreach(var w in s.Windows){if(!s.Remaining(w.Minutes,now).HasValue)continue;var remaining=w.ResetUtc-now;string cycle=s.AccountKey+":"+w.Minutes+":"+w.ResetUtc.Ticks;var crossed=points.Where(p=>remaining>TimeSpan.Zero&&remaining<=TimeSpan.FromMinutes(p)&&!cfg.SentResetReminders.Contains(cycle+":"+p)).ToArray();if(crossed.Length==0)continue;foreach(int point in crossed)cfg.SentResetReminders.Add(cycle+":"+point);messages.Add(new QuotaResetReminder{Minutes=w.Minutes,LeadMinutes=crossed.Min(),ResetUtc=w.ResetUtc,Text="Codex "+(w.Minutes==300?"五小时":"周")+"额度距离预计重置还有 "+BubbleLogic.TimeLeft(remaining)+"（"+w.ResetUtc.ToLocalTime().ToString("MM-dd HH:mm:ss")+"），实际额度以官方核验为准。"});Dirty=true;}cfg.SentResetReminders=cfg.SentResetReminders.Skip(Math.Max(0,cfg.SentResetReminders.Count-96)).ToList();return messages.ToArray();}
 public string[] ResetReminders(CodexQuotaSnapshot s,CodexQuotaConfig cfg,DateTime now){return ResetReminderNotices(s,cfg,now).Select(x=>x.Text).ToArray();}

}
